import re

def parse(lines):
    src_lines, src_recs = [], []
    ent_lines, ent_recs = [], []
    cap_lines, cap_recs = [], []
    skip = []
    term = ''
    for i, raw in enumerate(lines):
        s = raw.rstrip()
        if not s.strip():
            continue
        if s.startswith('#'):
            m = re.match(r'^#\s*Reconstructed via infocmp from file:\s*(?P<path>\S.*)$', s)
            if m:
                src_lines.append(i)
                src_recs.append({'source file': m.group('path').strip()})
            else:
                skip.append(i)
            continue
        if not s[0].isspace():
            body = s.rstrip(',').strip()
            parts = body.split('|')
            term = parts[0]
            desc = parts[-1] if len(parts) > 1 else ''
            aliases = parts[1:-1] if len(parts) > 2 else []
            ent_lines.append(i)
            ent_recs.append({'name': term, 'aliases': '|'.join(aliases), 'description': desc})
            continue
        caps = re.findall(r'((?:\\.|[^,\\])+),', s.strip() + ('' if s.strip().endswith(',') else ','))
        got = False
        for c in caps:
            c = c.strip()
            if not c:
                continue
            m = re.match(r'^(?P<cap>[^=#@\s]+)(?:(?P<op>[=#])(?P<val>.*)|(?P<cancel>@))?$', c, re.S)
            if not m:
                continue
            got = True
            if m.group('op') == '=':
                typ, val = 'string', m.group('val')
            elif m.group('op') == '#':
                typ, val = 'numeric', m.group('val')
            elif m.group('cancel'):
                typ, val = 'cancelled', ''
            else:
                typ, val = 'boolean', 'true'
            cap_recs.append({'terminal': term, 'capability': m.group('cap'), 'type': typ, 'value': val})
        if got:
            cap_lines.append(i)
    blocks = []
    if src_recs:
        blocks.append({'name': 'source', 'kind': 'kv', 'lines': src_lines, 'records': src_recs})
    if ent_recs:
        blocks.append({'name': 'entries', 'kind': 'kv', 'lines': ent_lines, 'records': ent_recs})
    if cap_recs:
        blocks.append({'name': 'capabilities', 'kind': 'table', 'lines': cap_lines, 'records': cap_recs})
    return {'blocks': blocks, 'skip': skip}
